#include "marker_exact.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
#include <vector>
#include <string>
namespace garment::marker_exact {
struct Pt{double x,y;};struct Box{std::vector<Pt> sampled;double minX,maxX,minY,maxY,width,height;};
struct Option{double rotation,width,height;bool cross;Box box;};
struct Entry{Json piece;int instance;double area;std::vector<Option> options;};
struct Placed{double x,y,width,height;};
static constexpr double PI=3.14159265358979323846;
static double n(const Json& v,double fallback=0){if(v.is_number())return v.get<double>();if(v.is_boolean())return v.get<bool>()?1:0;if(v.is_string()){try{return std::stod(v.get<std::string>());}catch(...){return fallback;}}return fallback;}
static Json field(const Json& o,const char* k){return o.is_object()&&o.contains(k)?o[k]:Json();}
static double number(const Json& o,const char* k,double def=0){auto v=field(o,k);return v.is_null()?def:n(v,def);}
static bool truthy(const Json& v){if(v.is_null()||v==false||v==0||v=="")return false;return true;}
static Pt pt(const Json& p){return {number(p,"x"),number(p,"y")};}
static double areaSigned(const std::vector<Pt>& p){double a=0;for(size_t i=0;i<p.size();i++){const auto& x=p[i];const auto& y=p[(i+1)%p.size()];a+=x.x*y.y-y.x*x.y;}return a*.5;}
static std::vector<Pt> boundary(const Json& piece,int segments){std::vector<Pt> sampled;std::vector<double> allowances;auto points=field(piece,"points");if(!points.is_array()||points.size()<3)return sampled;auto curves=field(piece,"curves"),overrides=field(piece,"edgeSeamAllowances");for(size_t e=0;e<points.size();e++){Pt a=pt(points[e]),b=pt(points[(e+1)%points.size()]);std::string key=std::to_string(e);Json curve=curves.is_array()&&e<curves.size()?curves[e]:(curves.is_object()&&curves.contains(key)?curves[key]:Json());double allowance=number(piece,"seamAllowance");if(overrides.is_array()&&e<overrides.size()&&!overrides[e].is_null())allowance=n(overrides[e]);else if(overrides.is_object()&&overrides.contains(key)&&!overrides[key].is_null())allowance=n(overrides[key]);allowance=std::max(0.,allowance);int steps=curve.is_object()?std::max(2,segments):1;for(int k=0;k<steps;k++){double t=double(k)/steps,u=1-t;sampled.push_back(curve.is_object()?Pt{u*u*a.x+2*u*t*number(curve,"cx")+t*t*b.x,u*u*a.y+2*u*t*number(curve,"cy")+t*t*b.y}:a);allowances.push_back(allowance);}}
if(std::all_of(allowances.begin(),allowances.end(),[](double a){return a<=0;}))return sampled;
bool ccw=areaSigned(sampled)>0;std::vector<Pt> out;for(size_t i=0;i<sampled.size();i++){auto p=sampled[i],pr=sampled[(i+sampled.size()-1)%sampled.size()],nx=sampled[(i+1)%sampled.size()];auto unit=[](double x,double y){double d=std::hypot(x,y);return Pt{x/(d?d:1),y/(d?d:1)};};Pt in=unit(p.x-pr.x,p.y-pr.y),ex=unit(nx.x-p.x,nx.y-p.y);Pt ni=ccw?Pt{in.y,-in.x}:Pt{-in.y,in.x},no=ccw?Pt{ex.y,-ex.x}:Pt{-ex.y,ex.x};double ai=allowances[(i+sampled.size()-1)%sampled.size()],ao=allowances[i];Pt a{p.x+ni.x*ai,p.y+ni.y*ai},b{p.x+no.x*ao,p.y+no.y*ao};double denominator=in.x*ex.y-in.y*ex.x;Pt result;if(std::abs(denominator)<1e-7){result={p.x+(ni.x*ai+no.x*ao)*.5,p.y+(ni.y*ai+no.y*ao)*.5};}else{double dx=b.x-a.x,dy=b.y-a.y,t=(dx*ex.y-dy*ex.x)/denominator;result={a.x+in.x*t,a.y+in.y*t};}double dx=result.x-p.x,dy=result.y-p.y,d=std::hypot(dx,dy),limit=std::max({ai,ao,.001})*3.5;if(d>limit)result={p.x+dx/d*limit,p.y+dy/d*limit};out.push_back(result);}return out;}
static double normRot(double d){double v=std::fmod(d,360);if(v>180)v-=360;if(v<=-180)v+=360;return v;}
static std::vector<Option> orientations(const Json& piece){double base=normRot(-number(piece,"grainAngleDeg"));std::vector<double> angles={base};if(truthy(field(field(piece,"marker"),"allowCrossGrain")))angles.push_back(normRot(base+90));std::vector<Option> result;for(size_t index=0;index<angles.size();index++){double rotation=normRot(angles[index]);bool duplicate=false;for(auto& opt:result)if(std::round(normRot(opt.rotation)*1000)==std::round(rotation*1000))duplicate=true;if(duplicate)continue;auto sampled=boundary(piece,10);double c=std::cos(rotation*PI/180),s=std::sin(rotation*PI/180);Box b; b.minX=b.minY=std::numeric_limits<double>::infinity();b.maxX=b.maxY=-std::numeric_limits<double>::infinity();for(auto p:sampled){Pt v{p.x*c-p.y*s,p.x*s+p.y*c};b.sampled.push_back(v);b.minX=std::min(b.minX,v.x);b.maxX=std::max(b.maxX,v.x);b.minY=std::min(b.minY,v.y);b.maxY=std::max(b.maxY,v.y);}b.width=b.maxX-b.minX;b.height=b.maxY-b.minY;result.push_back({rotation,b.width,b.height,index>0,b});}return result;}
static bool overlap(const Placed& a,const Placed& b,double gap){return !(a.x+a.width+gap<=b.x||b.x+b.width+gap<=a.x||a.y+a.height+gap<=b.y||b.y+b.height+gap<=a.y);}
Json buildMarker(const Json& project,double fabricWidth,double gap,const Json& settings){Json fid=field(settings,"fabricId");if(fid.is_null()||fid==""||fid==false)fid=nullptr;std::vector<Entry> entries;auto pieces=field(project,"pieces");if(pieces.is_array())for(const auto& piece:pieces){Json pf=field(piece,"fabricId");if(!truthy(pf))pf="main";if(!fid.is_null()&&pf!=fid)continue;auto opts=orientations(piece);if(opts.empty())continue;double q=number(piece,"cutQuantity",1);if(q==0)q=1;int quantity=std::max(1,std::min(99,int(std::floor(q+.5))));double a=std::abs(areaSigned(boundary(piece,12)));for(int i=0;i<quantity;i++)entries.push_back({piece,i,a,opts});}
std::stable_sort(entries.begin(),entries.end(),[](const Entry&a,const Entry&b){double diff=b.area-a.area;if(std::abs(diff)>1e-6)return diff<0;auto longest=[](const Entry& e){double v=0;for(auto& o:e.options)v=std::max(v,std::max(o.width,o.height));return v;};return longest(a)>longest(b);});
Json placements=Json::array(),unplaced=Json::array();std::vector<Placed> placed;int unused=0;double placedArea=0;
for(const auto& e:entries){std::vector<double> xs={0},ys={0};double oldLength=0;for(auto p:placed){xs.push_back(p.x+p.width+gap);ys.push_back(p.y+p.height+gap);oldLength=std::max(oldLength,p.y+p.height);}auto sortUnique=[](std::vector<double>& v){std::sort(v.begin(),v.end());v.erase(std::unique(v.begin(),v.end()),v.end());};sortUnique(xs);sortUnique(ys);bool found=false;double bestScore=0,bx=0,by=0;const Option* chosen=nullptr;for(const auto& o:e.options)for(double y:ys)for(double x:xs){if(x+o.width>fabricWidth+1e-6)continue;Placed candidate{x,y,o.width,o.height};bool blocked=false;for(auto existing:placed)if(overlap(candidate,existing,gap)){blocked=true;break;}if(blocked)continue;double score=std::max(oldLength,y+o.height)*1000000+y*10000+(fabricWidth-(x+o.width))*10+x;if(!found||score<bestScore){found=true;bestScore=score;bx=x;by=y;chosen=&o;}}if(!found){unused++;double minimum=std::numeric_limits<double>::infinity();for(auto& o:e.options)minimum=std::min(minimum,o.width);unplaced.push_back({{"pieceId",field(e.piece,"id")},{"instance",e.instance},{"name",field(e.piece,"name")},{"minimumWidthCm",std::isfinite(minimum)?Json(minimum):Json()},{"reason",minimum>fabricWidth?"too-wide":"no-space"}});continue;}const auto& o=*chosen;Json outline=Json::array();for(auto p:o.box.sampled)outline.push_back({{"x",bx+p.x-o.box.minX},{"y",by+p.y-o.box.minY}});placements.push_back({{"pieceId",field(e.piece,"id")},{"instance",e.instance},{"name",field(e.piece,"name")},{"x",bx},{"y",by},{"width",o.width},{"height",o.height},{"rotationDeg",o.rotation},{"rotated",o.cross},{"crossGrain",o.cross},{"area",e.area},{"outline",outline}});placed.push_back({bx,by,o.width,o.height});placedArea+=e.area;}
double length=0;for(auto p:placed)length=std::max(length,p.y+p.height);double markerArea=fabricWidth*std::max(length,.001);return {{"fabricId",fid},{"width",fabricWidth},{"length",length},{"gap",gap},{"placements",placements},{"efficiency",markerArea>0?placedArea/markerArea:0},{"unusedPieces",unused},{"requestedPieces",entries.size()},{"unplaced",unplaced}};
}
}
